# owner: platform
"""Seating charts: students sorted by last name, in rows."""

from typing import List, Sequence

from rosterkit.models import Student


def _sort_key(student: Student):
    return (student.last_name.lower(), student.first_name.lower())


def _row_line(number: int, members: Sequence[Student]) -> str:
    names = " | ".join(item.display_name for item in members)
    return f"Row {number}: {names}"


def seat_rows(
    students: Sequence[Student], seats_per_row: int
) -> List[str]:
    """One line of text per row, ordered by last name."""
    if seats_per_row <= 0:
        raise ValueError("seats per row must be positive")
    if not students:
        raise ValueError("no students to seat")
    ordered = sorted(students, key=_sort_key)
    step = seats_per_row
    return [
        _row_line(start // step + 1, ordered[start:start + step])
        for start in range(0, len(ordered), step)
    ]
