cat > tests/test_seating.py <<'EOF'
# owner: platform
import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student


def make(last, first):
    return Student(last + first, last, first, "A")


class SeatRowsTests(unittest.TestCase):
    def test_sorted_and_chunked(self):
        people = [
            make("Halloway", "Juno"),
            make("Zane", "Ola"),
            make("Dunmere", "Piet"),
        ]
        self.assertEqual(
            seat_rows(people, 2),
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Zane, Ola"
            ]
        )

    def test_first_name_breaks_ties(self):
        people = [make("Lane", "Bea"), make("Lane", "Abe")]
        lines = seat_rows(people, 5)
        self.assertEqual(
            lines, ["Row 1: Lane, Abe | Lane, Bea"]
        )

    def test_bad_seat_counts(self):
        people = [make("Lane", "Bea")]
        for seats in (0, -3):
            with self.assertRaises(ValueError):
                seat_rows(people, seats)

    def test_no_students(self):
        with self.assertRaises(ValueError):
            seat_rows([], 3)
